  "HIGH-WATER MARK": ["МАКСИМУМ БАЛАНСА", "उच्चतम स्तर", "MÁXIMO HISTÓRICO", "MASSIMO STORICO", "历史最高值", "最高水位標", "MAXIM ISTORIC"],
